def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    MOD = 1_000_000_007
    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, MOD)

    width = len(alphabet)
    char_index = {ch: i for i, ch in enumerate(alphabet)}

    transitions = [[-1] * width]
    failure = [0]
    forbidden = [False]

    for pattern in banned:
        state = 0
        for ch in pattern:
            c = char_index[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * width)
                failure.append(0)
                forbidden.append(False)
            state = transitions[state][c]
        forbidden[state] = True

    queue = deque()
    for c in range(width):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        fallback = failure[state]
        forbidden[state] |= forbidden[fallback]

        for c in range(width):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[fallback][c]
            else:
                failure[child] = transitions[fallback][c]
                queue.append(child)

    safe_states = [
        state for state in range(len(transitions)) if not forbidden[state]
    ]
    index = {state: i for i, state in enumerate(safe_states)}
    size = len(safe_states)

    matrix = [[0] * size for _ in range(size)]
    for i, state in enumerate(safe_states):
        for target in transitions[state]:
            if not forbidden[target]:
                matrix[i][index[target]] += 1

    def square(matrix):
        result = [[0] * size for _ in range(size)]
        for i, row in enumerate(matrix):
            output = result[i]
            for k, value in enumerate(row):
                if value:
                    other = matrix[k]
                    for j in range(size):
                        output[j] += value * other[j]
            for j in range(size):
                output[j] %= MOD
        return result

    counts = [0] * size
    counts[index[0]] = 1

    while n:
        if n & 1:
            updated = [0] * size
            for i, count in enumerate(counts):
                if count:
                    row = matrix[i]
                    for j in range(size):
                        updated[j] += count * row[j]
            counts = [value % MOD for value in updated]

        n >>= 1
        if n:
            matrix = square(matrix)

    return sum(counts) % MOD
